USER_TEXT = set()
for k, (g, st) in SCEN.items():
    for val in json.dumps(st).split('"'):
        if len(val) > 3: USER_TEXT.add(val)
# Wording fixed by statute (Texas Bus. & Com. Code 541.102(b), (c); Louisiana SB 386): not the generator's choice.
USER_TEXT.update(["NOTICE: We may sell your sensitive personal data.", "NOTICE: We may sell your biometric personal data."])

with sync_playwright() as p:
    b = p.chromium.launch()
    ctx = b.new_context(viewport={"width": 1600, "height": 900}, accept_downloads=True)
    ctx.add_init_script("try{localStorage.setItem('cc-consent', JSON.stringify({v:1, ts:Date.now(), groups:{C0001:true,C0002:false,C0003:false,C0004:false}}));}catch(e){}")
    page = ctx.new_page()
    errors = []
    page.on("pageerror", lambda e: errors.append("pageerror: " + str(e)))
    missing = []
    page.on("response", lambda r: missing.append(r.url) if r.status == 404 else None)
    page.on("console", lambda m: errors.append("console: " + m.text) if m.type == "error" and "404" not in m.text else None)
    page.goto(f"http://127.0.0.1:{PORT}/notice-generators.html")
    page.wait_for_function("window.__NG && document.querySelector('#ng-panel-pn .ng-sec')")
    check(not errors, "no errors on load " + json.dumps(errors[:5]))
    check(page.evaluate("typeof ACTIVITIES !== 'undefined' && ACTIVITIES.length === 71"), "readiness activities available (71)")

    # ---- scenarios
    for name, (gkey, state) in SCEN.items():
        res = page.evaluate("""([gkey, state]) => {
            const g = window.__NG.GENS.find(x => x.key === gkey);
            const r = g.build(JSON.parse(JSON.stringify(state)));
            const text = window.__NG.blocksToText(r.blocks) + "\\n" + (r.extraBlocks ? window.__NG.blocksToText(r.extraBlocks) : "") + "\\n" + (r.extra ? r.extra.replace(/<[^>]+>/g, " ") : "");
            return {text, checks: r.checks.map(c => [c.id, c.status, c.note]), banner: (r.banner || []).length};
        }""", [gkey, state])
        txt = res["text"]
        scrub = txt
        for u in sorted(USER_TEXT, key=len, reverse=True):
            scrub = scrub.replace(u, " ")
        scrub = re.sub(r"\b\d{1,2} May \d{4}\b", " ", scrub)  # the month, not the qualifier
        hits = sorted(set(m.group(0) for m in BAD.finditer(scrub)))
        check(not hits, f"{name}: no qualifiers or junk in generated text {hits}")
        check(EM not in txt, f"{name}: no em dash")
        dd = re.findall(r".{20}(?<!\.)\.\.(?!\.).{0,10}", txt)
        check(not dd, f"{name}: no doubled full stop {dd[:2]}")
        ex = EXPECT[name]
        for t in ex["texts"] + ex.get("texts2", []):
            check(t in txt, f"{name}: contains '{t}'")
        for t in ex["notexts"]:
            check(t not in txt, f"{name}: does not contain '{t}'")
        rows = {c[0]: c[1] for c in res["checks"]}
        allnotes = " ".join(c[2] for c in res["checks"])
        for t in ex.get("notes", []):
            check(t in allnotes, f"{name}: check notes mention '{t}'")
        for rid, st in ex["rows"].items():
            check(rows.get(rid) == st, f"{name}: row {rid} is {st} (got {rows.get(rid)})")
        if ex.get("uk_only"):
            stray = re.findall(r".{0,30}(?<!UK )\bGDPR\b.{0,10}", txt)
            check(not stray, f"{name}: every GDPR reference is to the UK GDPR {stray[:2]}")
        if ex.get("ph_missing") and "[" in txt:
            check(any(st == "missing" for st in rows.values()), f"{name}: a placeholder comes with a missing row")
        if ex.get("banner"):
            check(res["banner"] > 0, f"{name}: prohibited banner raised")
        open(os.path.join(SHOTS, name + ".txt"), "w", encoding="utf-8").write(txt + "\n\nCHECKS\n" + "\n".join(" | ".join(c) for c in res["checks"]))

